-- RAW ENTITY: Order
-- Grain: one row per order transaction
-- ID: hashed primary key — BASE64(SHA256('order-' || order_id))
-- Doctrine: Orders link to Customers via a Reference Carrier (Customer STRUCT).
--           The relationship is declared HERE, not ad-hoc joined downstream.

{{ config(tags=['raw_order']) }}

SELECT
    base64(sha256('order-' || CAST(O.order_id AS VARCHAR))) AS ID,
    CAST(O.order_date AS DATE) AS OrderDate,
    O.amount AS Amount,
    -- Reference Carrier: holds Customer's identity, declares the relationship
    STRUCT(
        base64(sha256(O.source_system || '-' || CAST(O.customer_id AS VARCHAR)))
    ) AS Customer,
    -- System STRUCT
    STRUCT(
        O.source_system AS SourceSystem,
        O.order_id AS SourceOrderID
    ) AS Source
FROM {{ source('tutorial', 'orders') }} AS O
